"""BAT-02 batch scheduler error-handling runner."""

from typing import Any


def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Run scheduled jobs sequentially, applying each job's error policy."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        retries = job["on_error"]["retries"]
        attempts = 0

        if policy == "RETRY":
            for _ in range(retries + 1):
                attempts += 1
                try:
                    executor(job)
                except Exception:
                    continue
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                break
            continue

        attempts = 1
        try:
            executor(job)
        except Exception:
            if policy == "CONTINUE":
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "skip",
                        "audits": ["BATCH_ROWSKIP"],
                    }
                )
                continue

            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "abort",
                    "audits": [],
                }
            )
            break

        run_log.append(
            {
                "name": job["name"],
                "attempts": attempts,
                "outcome": "ok",
                "audits": [],
            }
        )

    return run_log
